<!--
 * 灰度实验管理页面
 *
 * <p>消息通道灰度发布实验管理，支持创建实验、编辑、查看分桶分配、停止实验等操作。
 *
 * @path apps/message-web/src/views/canary/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 灰度实验管理（列表页）
 * <p>消费后端契约 CanaryController（src/api/canary.ts，auto-generated by bash/gen-contract.py）：
 * createExperiment() 创建灰度实验，assignBucket() 查询分桶分配结果。
 * 顶部快速创建表单，列表展示实验及其操作。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { Page } from '@ydsz/common-ui';
import { createLogger } from '@ydsz-core/shared/utils';
import { onMounted, reactive, ref } from 'vue';

import { assignBucket, createExperiment } from '#/api/canary';
import { YdBadge, YdButtonBase, YdCard, YdCardContent, YdDialog, YdDialogContent, YdDialogFooter, YdDialogHeader, YdDialogTitle, YdDialogDescription, YdInput, YdSelectBase, YdSelectContentBase, YdSelectItemBase, YdSelectTriggerBase, YdSelectValueBase, YdTextarea, YdTable, YdTableColumn, YdForm, YdFormItem, YdNumberFieldInput } from '@ydsz-core/ydsz-ui';

defineOptions({ name: 'CanaryManagement' });

const logger = createLogger('canary-management');

/** 实验列表数据（灰度实验暂无 list 接口，前端维护已创建记录） */
const experimentList = ref<CanaryExperimentRow[]>([]);

/** 加载状态 */
const loading = ref(false);

/** 快速创建表单 — 实验名称 */
const quickForm = reactive({
  experimentName: '',
  templateCode: '',
  channel: '',
  canaryPercent: 10,
  metricsGoal: '',
});

/** 快速创建表单可见性 */
const quickCreateVisible = ref(false);

/** 分桶分配结果弹窗可见性 */
const bucketVisible = ref(false);

/** 分桶分配结果 */
const bucketResult = ref('');

/** 查询分桶表单 */
const bucketForm = reactive({
  experimentId: '',
  requestKey: '',
});

/** 实验状态标签类型 */
function getStatusType(status?: string): 'success' | 'danger' | 'warning' | 'info' {
  const upper = (status ?? '').toUpperCase();
  if (upper === 'RUNNING' || upper === 'ACTIVE') return 'success';
  if (upper === 'STOPPED' || upper === 'TERMINATED') return 'danger';
  if (upper === 'DRAFT') return 'warning';
  return 'info';
}

/** 实验状态标签 YdBadge variant */
function getStatusVariant(status?: string): 'default' | 'destructive' | 'outline' | 'secondary' {
  const type = getStatusType(status);
  if (type === 'danger') return 'destructive';
  if (type === 'warning') return 'outline';
  if (type === 'info') return 'secondary';
  return 'default';
}

/** 实验状态标签文本 */
function getStatusLabel(status?: string): string {
  const labels: Record<string, string> = {
    RUNNING: '运行中',
    ACTIVE: '运行中',
    STOPPED: '已停止',
    TERMINATED: '已停止',
    DRAFT: '草稿',
  };
  return labels[(status ?? '').toUpperCase()] ?? status ?? '-';
}

/** 灰度实验行数据结构 */
interface CanaryExperimentRow {
  id: string;
  name: string;
  channel: string;
  status: string;
  trafficPercentage: number;
  createdAt: string;
}

/** 加载实验列表（前端本地维护，实际项目中可扩展为分页接口） */
function loadExperiments(): void {
  loading.value = true;
  // 合约当前仅有 createExperiment 和 assignBucket 两个端点，无列表接口；
  // 实验记录由前端本地维护（创建后追加）。预留扩展点：后续接入 listExperiment 接口。
  loading.value = false;
}

/** 快速创建实验 */
async function handleQuickCreate(): Promise<void> {
  if (!quickForm.experimentName.trim()) {
    showToast.warning('请输入实验名称');
    return;
  }
  if (!quickForm.channel.trim()) {
    showToast.warning('请选择通道');
    return;
  }
  try {
    const experimentId = await createExperiment({
      experimentName: quickForm.experimentName.trim(),
      templateCode: quickForm.templateCode.trim() || undefined,
      channel: quickForm.channel.trim(),
      canaryPercent: quickForm.canaryPercent,
      metricsGoal: quickForm.metricsGoal.trim() || undefined,
    });
    // 添加到本地列表
    const newExperiment: CanaryExperimentRow = {
      id: experimentId ?? `exp-${Date.now()}`,
      name: quickForm.experimentName.trim(),
      channel: quickForm.channel.trim(),
      status: 'RUNNING',
      trafficPercentage: quickForm.canaryPercent,
      createdAt: new Date().toISOString().replace('T', ' ').slice(0, 19),
    };
    experimentList.value.unshift(newExperiment);
    showToast.success('创建实验成功');
    quickCreateVisible.value = false;
    resetQuickForm();
  } catch (error) {
    logger.warn('创建灰度实验失败: {}', error);
    // 错误提示由 errorMessageResponseInterceptor 统一处理
  }
}

/** 重置快速创建表单 */
function resetQuickForm(): void {
  quickForm.experimentName = '';
  quickForm.templateCode = '';
  quickForm.channel = '';
  quickForm.canaryPercent = 10;
  quickForm.metricsGoal = '';
}

/** 查看分桶分配 */
async function handleViewBucket(row: CanaryExperimentRow): Promise<void> {
  bucketForm.experimentId = row.id;
  bucketForm.requestKey = '';
  bucketResult.value = '';
  bucketVisible.value = true;
}

/** 执行分桶查询 */
async function handleAssignBucket(): Promise<void> {
  if (!bucketForm.experimentId.trim()) {
    showToast.warning('请输入实验ID');
    return;
  }
  if (!bucketForm.requestKey.trim()) {
    showToast.warning('请输入请求键');
    return;
  }
  try {
    const result = await assignBucket({
      experimentId: bucketForm.experimentId.trim(),
      requestKey: bucketForm.requestKey.trim(),
    });
    bucketResult.value = result ?? '-';
  } catch (error) {
    logger.warn('查询分桶分配失败: {}', error);
    // 错误提示由 errorMessageResponseInterceptor 统一处理
  }
}

/** 停止实验 */
async function handleStopExperiment(row: CanaryExperimentRow): Promise<void> {
  try {
    await ydszConfirm(
      `确定停止实验「${row.name}」吗？停止后灰度流量将切回主版本。`,
      '停止确认',
      { type: 'warning' },
    );
  } catch {
    logger.debug('用户取消停止实验操作');
    return;
  }
  // 合约暂无 stopExperiment 接口，前端本地更新状态
  const target = experimentList.value.find((item) => item.id === row.id);
  if (target) {
    target.status = 'STOPPED';
  }
  showToast.success('实验已停止');
}

/** 编辑实验 */
function handleEdit(row: CanaryExperimentRow): void {
  logger.info('编辑实验: id={}', row.id);
  // 合约暂无 updateExperiment 接口，预留扩展
  showToast.info('编辑功能待后端接口支持');
}

onMounted(() => {
  loadExperiments();
});
</script>

<template>
  <Page auto-content-height>
    <div class="canary-container p-4">
      <!-- 顶部快速创建 -->
      <YdCard class="mb-4">
        <YdCardContent class="flex items-center justify-between pt-6">
          <h3 class="text-base font-medium">灰度实验管理</h3>
          <YdButtonBase @click="quickCreateVisible = true">
            创建实验
          </YdButtonBase>
        </YdCardContent>
      </YdCard>

      <!-- 实验列表 -->
      <YdCard>
        <YdCardContent class="pt-6">
          <YdTable loading="loading" :data="experimentList" stripe border style="width: 100%">
            <YdTableColumn type="index" label="序号" width="60" align="center" />
            <YdTableColumn prop="name" label="实验名称" min-width="160" />
            <YdTableColumn prop="channel" label="通道" width="120">
              <template #default="{ row }">
                <YdBadge variant="secondary">{{ row.channel }}</YdBadge>
              </template>
            </YdTableColumn>
            <YdTableColumn label="状态" width="100" align="center">
              <template #default="{ row }">
                <YdBadge :variant="getStatusVariant(row.status)">
                  {{ getStatusLabel(row.status) }}
                </YdBadge>
              </template>
            </YdTableColumn>
            <YdTableColumn label="灰度流量" width="120" align="center">
              <template #default="{ row }">
                <span class="font-mono text-blue-600">{{ row.trafficPercentage }}%</span>
              </template>
            </YdTableColumn>
            <YdTableColumn prop="createdAt" label="创建时间" width="180" />
            <YdTableColumn label="操作" width="260" fixed="right" align="center">
              <template #default="{ row }">
                <YdButtonBase size="sm" variant="link" @click="handleEdit(row)">
                  编辑
                </YdButtonBase>
                <YdButtonBase size="sm" variant="link" @click="handleViewBucket(row)">
                  查看分配
                </YdButtonBase>
                <YdButtonBase
                  size="sm"
                  variant="link"
                  class="text-destructive"
                  :disabled="row.status === 'STOPPED'"
                  @click="handleStopExperiment(row)"
                >
                  停止
                </YdButtonBase>
              </template>
            </YdTableColumn>
          </YdTable>

          <!-- 空状态提示 -->
          <div
            v-if="experimentList.length === 0 && !loading"
            class="py-12 text-center text-muted-foreground"
          >
            暂无灰度实验，点击右上角「创建实验」按钮开始
          </div>
        </YdCardContent>
      </YdCard>

      <!-- 快速创建弹窗 -->
      <YdDialog v-model:open="quickCreateVisible">
        <YdDialogContent class="max-w-[520px]">
          <YdDialogHeader>
            <YdDialogTitle>创建灰度实验</YdDialogTitle>
          </YdDialogHeader>
          <YdForm :model="quickForm" label-width="100px">
            <YdFormItem label="实验名称" required>
              <YdInput
                v-model="quickForm.experimentName"
                placeholder="请输入实验名称"
              />
            </YdFormItem>
            <YdFormItem label="模板编码">
              <YdInput
                v-model="quickForm.templateCode"
                placeholder="关联模板编码（可选）"
              />
            </YdFormItem>
            <YdFormItem label="通道" required>
              <YdSelectBase v-model="quickForm.channel">
                <YdSelectTriggerBase class="w-full">
                  <YdSelectValueBase placeholder="请选择通道" />
                </YdSelectTriggerBase>
                <YdSelectContentBase>
                  <YdSelectItemBase value="EMAIL">邮件</YdSelectItemBase>
                  <YdSelectItemBase value="SMS">短信</YdSelectItemBase>
                  <YdSelectItemBase value="INBOX">站内信</YdSelectItemBase>
                  <YdSelectItemBase value="WEBHOOK">Webhook</YdSelectItemBase>
                </YdSelectContentBase>
              </YdSelectBase>
            </YdFormItem>
            <YdFormItem label="灰度比例">
              <div class="flex items-center">
                <YdNumberFieldInput
                  v-model="quickForm.canaryPercent"
                  :min="1"
                  :max="100"
                  :step="5"
                  class="w-full"
                />
                <span class="ml-2 text-muted-foreground">%</span>
              </div>
            </YdFormItem>
            <YdFormItem label="目标指标">
              <YdTextarea
                v-model="quickForm.metricsGoal"
                placeholder="灰度实验目标指标（可选）"
              />
            </YdFormItem>
          </YdForm>
          <YdDialogFooter>
            <YdButtonBase variant="outline" @click="quickCreateVisible = false">取消</YdButtonBase>
            <YdButtonBase @click="handleQuickCreate">确认创建</YdButtonBase>
          </YdDialogFooter>
        </YdDialogContent>
      </YdDialog>

      <!-- 分桶分配查询弹窗 -->
      <YdDialog v-model:open="bucketVisible">
        <YdDialogContent class="max-w-[520px]">
          <YdDialogHeader>
            <YdDialogTitle>灰度分桶分配查询</YdDialogTitle>
          </YdDialogHeader>
          <YdForm :model="bucketForm" label-width="100px">
            <YdFormItem label="实验ID">
              <YdInput v-model="bucketForm.experimentId" placeholder="实验ID" />
            </YdFormItem>
            <YdFormItem label="请求键">
              <YdInput v-model="bucketForm.requestKey" placeholder="请求键（用户ID等）" />
            </YdFormItem>
          </YdForm>
          <div v-if="bucketResult" class="mt-4 rounded bg-muted p-3">
            <span class="text-sm text-muted-foreground">分配结果：</span>
            <span class="ml-2 font-mono font-bold text-blue-600">{{ bucketResult }}</span>
          </div>
          <YdDialogFooter>
            <YdButtonBase variant="outline" @click="bucketVisible = false">关闭</YdButtonBase>
            <YdButtonBase @click="handleAssignBucket">查询</YdButtonBase>
          </YdDialogFooter>
        </YdDialogContent>
      </YdDialog>
    </div>
  </Page>
</template>
